import './_header.scss'
import '../../assets/images/logo.png'

function Header() {
    return (
        <>
            <div id="header">
                <div className="container">
                    <div className="header">
                        {/*<h1>A</h1>*/}
                        <img src={logo} alt=""/>
                        <p>AJONIX</p>

                    </div>
                </div>
            </div>
        </>
    )
}



export default Header;
